mapper.select:
SELECT sti.id, sti.code, sti.approve_status AS approveStatus, sti.approve_user_id AS approveUserId, sti.approve_user_name AS approveUserName, sti.approve_time AS approveTime, sti.invalid_status AS invalidStatus, sti.transfer_out_user_id AS transferOutUserId, sti.transfer_out_user_name AS transferOutUserName, sti.transfer_out_dept_id AS transferOutDeptId, sti.transfer_out_dept_name AS transferOutDeptName, sti.transfer_in_user_id AS transferInUserId, sti.transfer_in_user_name AS transferInUserName, sti.transfer_in_dept_id AS transferInDeptId, sti.transfer_in_dept_name AS transferInDeptName, sti.transfer_date AS transferDate, sti.remark, sti.create_time AS createTime, sti.create_user_name AS createUserName, std.id AS detailId, std.sku_no AS skuNo, std.sku_id AS skuId, std.product_name AS productName, std.transfer_qty AS transferQty, std.remark AS detailRemark FROM sample_transfer_info sti LEFT JOIN sample_transfer_detail std ON std.main_id = sti.id AND std.is_deleted = false WHERE ${params.sqlMap.default} AND sti.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sti.create_time DESC, std.id ASC

SELECT approve_status AS tabFlag, count(*) AS count FROM sample_transfer_info WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
